steps.code:
mutation {
  metaobjectDefinitionCreate(definition: {
    type: "depoimento",
    name: "Depoimento",
    fieldDefinitions: [
      { name: "Nome", key: "nome", type: "single_line_text_field" },
      { name: "Texto", key: "texto", type: "multi_line_text_field" }
    ]
  }) { metaobjectDefinition { id } userErrors { field message } }
}

mutation {
  metaobjectCreate(metaobject: {
    type: "depoimento",
    fields: [
      {key: "nome", value: "Ana"},
      {key: "texto", value: "Produto excelente, entrega rápida!"}
    ]
  }) { metaobject { id } userErrors { field message } }
}

query {
  metaobjects(type: "depoimento", first: 10) {
    nodes {
      id
      field(key: "nome") { value }
      field(key: "texto") { value }
    }
  }
}

mutation {
  metaobjectDefinitionCreate(definition: {
    type: "depoimento",
    name: "Depoimento",
    fieldDefinitions: [
      { name: "Nome", key: "nome", type: "single_line_text_field" },
      { name: "Texto", key: "texto", type: "multi_line_text_field" },
      { name: "Produto", key: "produto", type: "product_reference" }
    ]
  }) { metaobjectDefinition { id } userErrors { field message } }
}

query {
  metaobjects(type: "depoimento", first: 10) {
    nodes {
      field(key: "nome") { value }
      field(key: "produto") {
        reference {
          ... on Product { title }
        }
      }
    }
  }
}
